import pytest

@pytest.fixture
def app():
    app = Flask(__name__)
    app.config["PROPAGATE_EXCEPTIONS"] = False
    return app

class CustomException(Exception):
    pass

def test_teardown_request_order_and_exception(app):
    teardown_calls = []

    @app.teardown_request
    def teardown_1(exception):
        teardown_calls.append(("teardown_1", exception.__class__.__name__))

    @app.teardown_request
    def teardown_2(exception):
        teardown_calls.append(("teardown_2", exception.__class__.__name__))

    @app.route("/exception")
    def exception_view():
        raise CustomException("This is a custom exception")

    with app.test_request_context("/exception"):
        with pytest.raises(CustomException):
            app.full_dispatch_request()

    assert teardown_calls == [
        ("teardown_2", "NoneType"),
        ("teardown_1", "NoneType"),
    ]

def test_teardown_request_continues_on_exception_in_teardown(app):
    teardown_calls = []

    @app.teardown_request
    def teardown_raising(exception):
        teardown_calls.append(("teardown_raising", exception.__class__.__name__))
        raise ValueError("Teardown itself raised an error")

    @app.teardown_request
    def teardown_continuing(exception):
        teardown_calls.append(("teardown_continuing", exception.__class__.__name__))

    @app.route("/exception")
    def exception_view():
        raise CustomException("This is a custom exception")

    with pytest.raises(ValueError):  # Expect ValueError from teardown_raising
        with app.test_request_context("/exception"):
            app.full_dispatch_request()

    assert teardown_calls == [
        ("teardown_continuing", "CustomException"),
        ("teardown_raising", "CustomException"),
    ]
